import { Implement, implement } from '@orpc/nest';
import { contract } from '@repo/contracts';
import { Controller, Get } from '@nestjs/common';
import { SkipThrottle } from '@nestjs/throttler';
import { JobsService } from './jobs.service';

// No auth/company guards on purpose: this is the endpoint behind the
// public share link generated by JobsController#generateJobUrl, meant to
// be opened by people outside the company.
// The 'loginByEmail' throttler (5 req / 15 min) is registered globally and
// would otherwise apply to every route, blocking the public home page after a
// few reloads. The 'default' throttler (100 req / 2h per IP) still applies.
@SkipThrottle({ loginByEmail: true })
@Controller('/jobs')
export class PublicJobsController {
  constructor(private readonly jobsService: JobsService) {}

  @Get('/shared/:shareToken')
  @Implement(contract.jobs.getSharedJob)
  async getSharedJob() {
    return implement(contract.jobs.getSharedJob).handler(({ input }) => {
      const { shareToken } = input;
      return this.jobsService.getSharedJobByToken(shareToken);
    });
  }

  // Public job board (front home page): every PUBLISHED job, all companies.
  @Get('/public')
  @Implement(contract.jobs.listPublicJobs)
  async listPublicJobs() {
    return implement(contract.jobs.listPublicJobs).handler(() => {
      return this.jobsService.listPublicJobs();
    });
  }

  // Link returned by generateJobUrl for PUBLISHED jobs. Only published
  // jobs are served here; drafts/archived require a share token.
  @Get('/public/:jobId')
  @Implement(contract.jobs.getPublicJob)
  async getPublicJob() {
    return implement(contract.jobs.getPublicJob).handler(({ input }) => {
      const { jobId } = input;
      return this.jobsService.getPublicJob(jobId);
    });
  }

  @Get('/invite/:inviteToken')
  @Implement(contract.jobs.getJobByInvite)
  async getJobByInvite() {
    return implement(contract.jobs.getJobByInvite).handler(({ input }) => {
      const { inviteToken } = input;
      return this.jobsService.getJobByInviteToken(inviteToken);
    });
  }
}
